/* hero-whorl.js — the Synthe hero glyph field ("whorl").
   The mechanism is the luminance text field from the clone gallery's
   contentarch-textfields piece (itself a port of the reference's
   GlyphFieldScene): a grid of mono glyphs whose opacity follows a
   brightness model (opacity = brightness^0.6), with a per-cell twinkle
   inside the model and an entrance ripple from the model's centre.
   The shaders below are that renderer's own GLSL, kept verbatim.

   What is Synthe's here:
   - The brightness model is the Synthe Mark, rendered with a 3D
     treatment (layered extrusion, diagonal luminance gradient,
     speckle) and sampled to a 152x88 grid. Produced by
     hero-whorl-model.html; the method is documented in HERO2.md.
   - The glyph stream is coding symbols and Synthe terms, not the
     reference's claims phrases.
   - Hover does NOTHING. The reference's hover kill/dim bell is
     deliberately not wired: no pointer listeners exist in this file
     and uMouseInfluence is pinned to 0. (Founder's explicit call:
     no dark circle around the cursor.) Clicks do nothing either;
     the only ripple is the entrance ripple.
   - The loop pauses when the hero is off-screen (IntersectionObserver)
     and under prefers-reduced-motion a single static frame is drawn.

   Vanilla JS + WebGL2, zero dependencies, zero external requests.
   The font is the site's IBM Plex Mono (already loaded by the page).
   Auto-inits every <canvas data-hero-whorl>; also exposes
   window.initHeroWhorl(canvas) returning { grid, frames, simTime }. */
'use strict';

/* ---------------- data ---------------- */

var WHORL_TOKENS = ['synthe', '{', '}', '</>', '=>', ';', '(', ')',
  'const', 'let', 'fn', 'return', 'if', 'else', 'for', 'await', 'async',
  'import', 'export', 'null', 'true', 'false', '||', '&&', '!=', '===',
  '->', '::', 'prompt', 'checks', 'merge', 'kept', 'revert', 'loop',
  'round', 'test', 'diff', 'PR', 'token', 'model', 'agent', 'held-out'];
var WHORL_PHRASE = WHORL_TOKENS.join(' · ') + ' · ';
/* atlas = space + every distinct character of the stream, in order */
var WHORL_ATLAS = ' ' + Array.from(new Set(Array.from(WHORL_PHRASE)))
  .filter(function (ch) { return ch !== ' '; }).join('');

var WHORL_MODEL_COLS = 152;
var WHORL_MODEL_ROWS = 88;
/* display aspect of the model image = (cols/rows) * glyphAspect
   = (152/88) * 0.55 = 0.950, the Mark's own 275:290 aspect (0.948) */
var WHORL_SOURCE_ASPECT = 0.9483;
var WHORL_GLYPH_ASPECT = 0.55;
